{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Quercetin-3-O-glucuronide, a flavonoid glucuronide with physicochemical properties very similar to the query, was detected in perfused rat brain tissue, directly demonstrating that this structural class can achieve BBB penetration despite glucuronidation and high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin, a polar flavonoid C-glucoside, reached quantifiable cerebellum concentrations after intravenous dosing in rats, supporting meaningful CNS access for glycosylated flavonoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Camellianin B, a flavonoid glycoside, was detected in rat brain after intragastric administration, providing additional in vivo evidence that glycosylated flavonoids can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Orientin, a polar flavonoid C-glucoside, showed only low brain levels after intravenous administration attributed to high polarity, representing a counterexample where glycosylation limits CNS penetration.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Mefenamic acid glucuronide showed negligible brain uptake after oral dosing, indicating that not all glucuronides penetrate the CNS and providing a cautionary counterexample.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a flavonoid 3-O-glucoside, was shown to transfer across the blood-brain barrier in rat tissue distribution studies, supporting CNS access for polar flavonoid glycosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the closest direct analogue, quercetin-3-O-glucuronide, demonstrates BBB penetration for a flavonoid glucuronide, and multiple polar flavonoid glycosides reach brain in vivo; the few impermeable examples are less similar or involve different glucuronide/aglycone contexts, so meaningful CNS access is supported despite unfavorable passive-diffusion properties.",
  "evidence_gaps": [
    "No direct baicalin-specific brain-to-plasma ratio, CSF, or unbound brain concentration data are available in the provided evidence.",
    "Perfused-brain detection may not fully distinguish parenchymal uptake from vascular retention.",
    "The quantitative impact of efflux transporters on baicalin brain exposure is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

